-- The ownership ledger records where each supply-engine routine now comes from (3 Sep 2026).
--
-- Generated by `node scripts/checks/application_source_of_truth.test.mjs --emit-ledger-sync` after
-- the six supply_engine files were applied: fn_doc_expiry_scan and fn_supply_gap_scan were recorded
-- HISTORICAL_APPLICATION (their only definitions were in supabase/migrations_history) and now have a
-- canonical scripts/sql file; enqueue_supplier_invites, fn_company_indices and fn_index_slowdown_watch
-- still pointed at the file that defined them last. The fn_exec_meeting row the generator also
-- printed belongs to another change in flight and is left to it.
--
--   node scripts/apply_sql.mjs scripts/sql/supply_engine_routines_are_owned_by_their_canonical_files.sql --apply --ddl

update public.kernel_routine_ownership set
       ownership_class = 'QUOTESDONE_APPLICATION', classified_by_rule = 'R4_MANIFEST_DEFINES_IT',
       source_kind = 'MANIFEST', source_file = 'scripts/sql/supply_engine_invite_plan_is_real_and_held.sql',
       evidence = 'records source_file scripts/sql/the_company_wrote_down_when_not_to_send_and_nothing_read_it.sql, manifest order says scripts/sql/supply_engine_invite_plan_is_real_and_held.sql — reconciled mechanically 3 Sep 2026 (supply engine).'
 where schema_name = 'public' and routine_name = 'enqueue_supplier_invites'
   and coalesce(identity_args,'') = 'p_cap integer';

